  - exact bootq_1RB0RB_0LC1RB_1RA1LD_1LC0RB.
  - intros p _. apply lap_1RB0RB_0LC1RB_1RA1LD_1LC0RB.
  - intros t Ht p _. apply fire_1RB0RB_0LC1RB_1RA1LD_1LC0RB. exact Ht.
  - exact wit_1RB0RB_0LC1RB_1RA1LD_1LC0RB.
  - apply qcleb_QC_14. reflexivity.
Qed.

