    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_0LC1RD_0LC1LA_1LC0RD [SWin 1] (StC, S1) ltac:(vm_compute; reflexivity)
