  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := [SCycL 6 0; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := [SCycL 6 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := [SCycL 6 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := [SCycL 6 0; SWin 6; SWinL 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0RC0LA_1LD1RC_0LD1RB
      with (l := [SCycL 6 0; SWin 3]).
    vm_compute; reflexivity.
Qed.

