Lemma fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0RC0LC_1LD0RB_1LD1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0RC0LC_1LD0RB_1LD1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0RC0LC_1LD0RB_1LD1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0RC0LC_1LD0RB_1LD1RA : forall t, ~ In t pins_1RB0RB_0RC0LC_1LD0RB_1LD1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0RC0LC_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RB_0RC0LC_1LD0RB_1LD1RA : NonHalt tmm_1RB0RB_0RC0LC_1LD0RB_1LD1RA /\ QHBoundTr 32779478 tmm_1RB0RB_0RC0LC_1LD0RB_1LD1RA /\ QuasiHaltsTr tmm_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
Proof.
  apply (lap_qh_stage tmm_1RB0RB_0RC0LC_1LD0RB_1LD1RA pins_1RB0RB_0RC0LC_1LD0RB_1LD1RA Cc 1 20 32779478).
  - exact bootq_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
  - intros p _. apply lap_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
  - intros t Ht p _. apply fire_1RB0RB_0RC0LC_1LD0RB_1LD1RA. exact Ht.
  - exact wit_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
  - apply qcleb_QC_14. reflexivity.
Qed.

Theorem qhtr_1RB0RB_0RC0LC_1LD0RB_1LD1RA : NonHalt tm_1RB0RB_0RC0LC_1LD0RB_1LD1RA /\ QHBoundTr 32779478 tm_1RB0RB_0RC0LC_1LD0RB_1LD1RA /\ QuasiHaltsTr tm_1RB0RB_0RC0LC_1LD0RB_1LD1RA.
