(** 1RB0RB_0RC0LD_0RD0RB_1LD1RA *)
(** 1RB0RB_0RC0LD_0RD0RB_1LD1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RB_0RC0LD_0RD0RB_1LD1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S0 DR StC | StB, S1 => mk S0 DL StD
  | StC, S0 => mk S0 DR StD | StC, S1 => mk S0 DR StB
