(** ** The lap *)

Lemma lap_1RB0RB_0RC0LD_1LD0RB_1LD1RA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
