    apply (lap_of_run tm Cc true true cho_1RB0RB_0RC0LD_1LD0RB_1LD1RA B0_1RB0RB_0RC0LD_1LD0RB_1LD1RA B1_1RB0RB_0RC0LD_1LD0RB_1LD1RA 4 14 p j' [] []).
