    + exact (geo_1RB0RB_0RC0LD_1LD0RB_1LD1RA p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RB_0RC0LD_1LD0RB_1LD1RA : stepn tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA 20 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA 20 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA 20 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RB_0RC0LD_1LD0RB_1LD1RA : existsb (fun tg => cfires tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA c0 20 tg) pins_1RB0RB_0RC0LD_1LD0RB_1LD1RA = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_0RC0LD_1LD0RB_1LD1RA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_0RC0LD_1LD0RB_1LD1RA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_0RC0LD_1LD0RB_1LD1RA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_0RC0LD_1LD0RB_1LD1RA : forall t, ~ In t pins_1RB0RB_0RC0LD_1LD0RB_1LD1RA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 4]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 1]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_0RC0LD_1LD0RB_1LD1RA
      with (l := [SCycL 2 0; SWin 2; SWinL 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RB_0RC0LD_1LD0RB_1LD1RA : NonHalt tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA /\ QHBoundTr 32779478 tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA /\ QuasiHaltsTr tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
Proof.
  apply (lap_qh_stage tmm_1RB0RB_0RC0LD_1LD0RB_1LD1RA pins_1RB0RB_0RC0LD_1LD0RB_1LD1RA Cc 1 20 32779478).
  - exact bootq_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
  - intros p _. apply lap_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
  - intros t Ht p _. apply fire_1RB0RB_0RC0LD_1LD0RB_1LD1RA. exact Ht.
  - exact wit_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
  - apply qcleb_QC_14. reflexivity.
Qed.

Theorem qhtr_1RB0RB_0RC0LD_1LD0RB_1LD1RA : NonHalt tm_1RB0RB_0RC0LD_1LD0RB_1LD1RA /\ QHBoundTr 32779478 tm_1RB0RB_0RC0LD_1LD0RB_1LD1RA /\ QuasiHaltsTr tm_1RB0RB_0RC0LD_1LD0RB_1LD1RA.
