(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gsi_1RB0RB_0RC1RC_1LD0RC_0LD1LA : forall p j q0, cview p = (j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j A0_1RB0RB_0RC1RC_1LD0RC_0LD1LA.
