Lemma geo_1RB0RB_0RC1RC_1LD0RC_0LD1LA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_0RC1RC_1LD0RC_0LD1LA) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (KpCounter.cview_none_K p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_0RC1RC_1LD0RC_0LD1LA
