  - intros t Ht p _. apply fire_1RB0RB_1LA1LC_1LB0RD_0LC1RD. exact Ht.
  - exact wit_1RB0RB_1LA1LC_1LB0RD_0LC1RD.
  - apply qcleb_QC_14. reflexivity.
