Lemma gp_1RB0RB_1LC0RB_0LD1RA_0LD1RB : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Kp q0 ++ [S0]) [] j P0_1RB0RB_1LC0RB_0LD1RA_0LD1RB /\
  cden (Kp q0 ++ [S0]) [] j P1_1RB0RB_1LC0RB_0LD1RA_0LD1RB = Cc (Pos.succ p).
