Lemma lapi_1RB0RB_1LC0RB_0LD1RA_0LD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
