  - destruct (gz_1RB0RB_1LC0RB_0LD1RA_0LD1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 6). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RB_1LC0RB_0LD1RA_0LD1RB Z0_1RB0RB_1LC0RB_0LD1RA_0LD1RB Z1_1RB0RB_1LC0RB_0LD1RA_0LD1RB 0 6
               run_z_1RB0RB_1LC0RB_0LD1RA_0LD1RB (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RB_1LC0RB_0LD1RA_0LD1RB p j' q0 E) as (HA & HB).
    exists (2 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RB_1LC0RB_0LD1RA_0LD1RB P0_1RB0RB_1LC0RB_0LD1RA_0LD1RB P1_1RB0RB_1LC0RB_0LD1RA_0LD1RB 2 8
               run_p_1RB0RB_1LC0RB_0LD1RA_0LD1RB (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
