(** ** The lap *)

Lemma lap_1RB0RB_1LC0RB_0LD1RA_0LD1RB : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
