  - destruct (lapi_1RB0RB_1LC0RB_0LD1RA_0LD1RB p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_1LC0RB_0LD1RA_0LD1RB B0_1RB0RB_1LC0RB_0LD1RA_0LD1RB B1_1RB0RB_1LC0RB_0LD1RA_0LD1RB 2 8 p j' [] []).
    + exact run_ovf_1RB0RB_1LC0RB_0LD1RA_0LD1RB.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_1LC0RB_0LD1RA_0LD1RB p j' E).
    + exact (geo_1RB0RB_1LC0RB_0LD1RA_0LD1RB p j' E).
