(** ** Bootstrap *)

Lemma bootq_1RB0RB_1LC0RB_0LD1RA_0LD1RB : stepn tmm_1RB0RB_1LC0RB_0LD1RA_0LD1RB 7 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RB_1LC0RB_0LD1RA_0LD1RB 7 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RB_1LC0RB_0LD1RA_0LD1RB 7 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
