      with (l := [SWin 3]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_1LC0RB_0LD1RA_0LD1RB
      with (l := [SWin 3; SCycL 1 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_1LC0RB_0LD1RA_0LD1RB
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_1LC0RB_0LD1RA_0LD1RB
      with (l := [SWin 3; SCycL 1 0; SWin 2; SRotR 1; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_1LC0RB_0LD1RA_0LD1RB
      with (l := [SWin 3; SCycL 1 0; SWin 2; SRotR 1; SWin 1; SCycR 1; SWin 1]).
    vm_compute; reflexivity.
Qed.

