  - exact bootq_1RB0RB_1LC0RB_0LD1RA_0LD1RB.
  - intros p _. apply lap_1RB0RB_1LC0RB_0LD1RA_0LD1RB.
  - intros t Ht p _. apply fire_1RB0RB_1LC0RB_0LD1RA_0LD1RB. exact Ht.
  - exact wit_1RB0RB_1LC0RB_0LD1RA_0LD1RB.
  - apply qcleb_QC_14. reflexivity.
