Theorem qhtr_1RB0RB_1LC0RB_0LD1RA_0LD1RB : NonHalt tm_1RB0RB_1LC0RB_0LD1RA_0LD1RB /\ QHBoundTr 32779478 tm_1RB0RB_1LC0RB_0LD1RA_0LD1RB /\ QuasiHaltsTr tm_1RB0RB_1LC0RB_0LD1RA_0LD1RB.
