(** 1RB0RB_1LC0RB_1LD1RC_0LC1RA *)
(** 1RB0RB_1LC0RB_1LD1RC_0LC1RA -- the real machine (its counter grows RIGHT). *)
Definition tm_1RB0RB_1LC0RB_1LD1RC_0LC1RA : TM := fun q s => match q, s with
  | StA, S0 => mk S1 DR StB | StA, S1 => mk S0 DR StB
  | StB, S0 => mk S1 DL StC | StB, S1 => mk S0 DR StB
  | StC, S0 => mk S1 DL StD | StC, S1 => mk S1 DR StC
