Lemma geo_1RB0RB_1LC0RB_1LD1RC_0LC1RA : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_1LC0RB_1LD1RC_0LC1RA) = lift (Cc (Pos.succ p)).
