    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_1LC1LD_0LC1RB_0RA1RA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_1LC1LD_0LC1RB_0RA1RA = Some t ->
