      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_1LC1LD_0LC1RB_0RA1RA
      with (l := [SWin 2]).
    vm_compute; reflexivity.
