      with (l := [SWin 5; SWin 2; SCycL 3 0; SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_1LC1LD_0LC1RB_0RA1RA
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_1LC1LD_0LC1RB_0RA1RA
      with (l := [SWin 5; SWin 1]).
    vm_compute; reflexivity.
  - (* D1 *)
