(** ** Anchor glue -- the only per-machine mathematics *)

Lemma gz_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p q0, cview p = (0, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z0_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0 Z1_1RB0RB_1LC1RA_1LB0LD_1RC0LC = Cc (Pos.succ p).
Proof.
  intros p q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p 0 q0 E) as (H1 & H2).
  unfold Cc_1RB0RB_1LC1RA_1LB0LD_1RC0LC, cden, Z0_1RB0RB_1LC1RA_1LB0LD_1RC0LC, Z1_1RB0RB_1LC1RA_1LB0LD_1RC0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma gp_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p j q0, cview p = (S j, Some q0) ->
  Cc p = cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P0_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\
  cden (Ap_Alph_00_10_1 q0 ++ [S0]) [] j P1_1RB0RB_1LC1RA_1LB0LD_1RC0LC = Cc (Pos.succ p).
Proof.
  intros p j q0 E. destruct (Alph_00_10_1.cview_some_Alph_00_10_1 p (S j) q0 E) as (H1 & H2).
  unfold Cc_1RB0RB_1LC1RA_1LB0LD_1RC0LC, cden, P0_1RB0RB_1LC1RA_1LB0LD_1RC0LC, P1_1RB0RB_1LC1RA_1LB0LD_1RC0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with j by lia.
  split.
  - rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
  - rewrite H2; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lapi_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RB_1LC1RA_1LB0LD_1RC0LC p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RB_1LC1RA_1LB0LD_1RC0LC Z0_1RB0RB_1LC1RA_1LB0LD_1RC0LC Z1_1RB0RB_1LC1RA_1LB0LD_1RC0LC 0 4
               run_z_1RB0RB_1LC1RA_1LB0LD_1RC0LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RB_1LC1RA_1LB0LD_1RC0LC P0_1RB0RB_1LC1RA_1LB0LD_1RC0LC P1_1RB0RB_1LC1RA_1LB0LD_1RC0LC 4 8
               run_p_1RB0RB_1LC1RA_1LB0LD_1RC0LC (Ap_Alph_00_10_1 q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (H1 & _).
  unfold Cc_1RB0RB_1LC1RA_1LB0LD_1RC0LC, cden, B0_1RB0RB_1LC1RA_1LB0LD_1RC0LC; cbn [c_st c_l c_h c_r].
  unfold sden; cbn [s_pre s_u s_a s_b s_post].
  replace (1 * j + 0) with (j) by lia.
  rewrite H1; cbn [rep app]. first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ].
Qed.

Lemma lbl_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall q l h r, lift (q,(l ++ [S0],h,r)) = lift (q,(l,h,r)).
Proof. intros. unfold lift; simpl. rewrite lift_side_app_blank. reflexivity. Qed.

Lemma geo_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p j, cview p = (S j, None) ->
  lift (cden [] [] j B1_1RB0RB_1LC1RA_1LB0LD_1RC0LC) = lift (Cc (Pos.succ p)).
Proof.
  intros p j E. destruct (Alph_00_10_1.cview_none_Alph_00_10_1 p j E) as (_ & H2).
  assert (HD : cden [] [] j B1_1RB0RB_1LC1RA_1LB0LD_1RC0LC
             = (StC, (rep [S0;S0] (S j) ++ [S1], S0, [S1]))).
  { unfold cden, B1_1RB0RB_1LC1RA_1LB0LD_1RC0LC, sden, sflat;
      cbn [c_st c_l c_h c_r s_pre s_u s_a s_b s_post].
    replace (1 * j + 1) with (S j) by lia.
    replace (0 * j + 0) with 0 by lia.
    cbn [rep app]. first [ reflexivity
      | rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  assert (HC : Cc (Pos.succ p) = (StC, ((rep [S0;S0] (S j) ++ [S1]) ++ [S0], S0, [S1]))).
  { unfold Cc_1RB0RB_1LC1RA_1LB0LD_1RC0LC. rewrite H2.
    first [ rewrite <- !app_assoc; reflexivity
        | cbn [app]; rewrite <- ?app_assoc; cbn [app]; rewrite ?app_nil_r; reflexivity ]. }
  rewrite HD, HC. rewrite !lbl_1RB0RB_1LC1RA_1LB0LD_1RC0LC. reflexivity.
Qed.

(** ** The lap *)

Lemma lap_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
Proof.
  intro p. destruct (cview p) as [j oq] eqn:E. destruct oq as [q0|].
  - destruct (lapi_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j q0 E) as (n & Hn & Hrun).
    exists n, (Cc (Pos.succ p)).
    split; [exact Hrun | split; [reflexivity | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_1LC1RA_1LB0LD_1RC0LC B0_1RB0RB_1LC1RA_1LB0LD_1RC0LC B1_1RB0RB_1LC1RA_1LB0LD_1RC0LC 4 8 p j' [] []).
    + exact run_ovf_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j' E).
    + exact (geo_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RB_1LC1RA_1LB0LD_1RC0LC : stepn tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC 4 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC 4 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC 4 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RB_1LC1RA_1LB0LD_1RC0LC : existsb (fun tg => cfires tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC c0 4 tg) pins_1RB0RB_1LC1RA_1LB0LD_1RC0LC = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_1LC1RA_1LB0LD_1RC0LC = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_1LC1RA_1LB0LD_1RC0LC p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_1LC1RA_1LB0LD_1RC0LC : forall t, ~ In t pins_1RB0RB_1LC1RA_1LB0LD_1RC0LC ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_via_ovf tm Cc Hi (StA, S0)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1]).
    vm_compute; reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 1]).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 2]).
    vm_compute; reflexivity.
  - (* D0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RB_1LC1RA_1LB0LD_1RC0LC
      with (l := [SWin 2; SRotL 1; SWin 1; SCycL 2 0; SWin 1; SWinL 3]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RB_1LC1RA_1LB0LD_1RC0LC : NonHalt tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\ QHBoundTr 32779478 tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\ QuasiHaltsTr tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
Proof.
  apply (lap_qh_stage tmm_1RB0RB_1LC1RA_1LB0LD_1RC0LC pins_1RB0RB_1LC1RA_1LB0LD_1RC0LC Cc 1 4 32779478).
  - exact bootq_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
  - intros p _. apply lap_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
  - intros t Ht p _. apply fire_1RB0RB_1LC1RA_1LB0LD_1RC0LC. exact Ht.
  - exact wit_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
  - apply qcleb_QC_14. reflexivity.
Qed.

Theorem qhtr_1RB0RB_1LC1RA_1LB0LD_1RC0LC : NonHalt tm_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\ QHBoundTr 32779478 tm_1RB0RB_1LC1RA_1LB0LD_1RC0LC /\ QuasiHaltsTr tm_1RB0RB_1LC1RA_1LB0LD_1RC0LC.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RB_1LC1RA_1LB0LD_1RC0LC). rewrite mirror_ok_1RB0RB_1LC1RA_1LB0LD_1RC0LC. exact qhtrm_1RB0RB_1LC1RA_1LB0LD_1RC0LC. Qed.

