  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RB_1LC1RD_0LB1RA_1LB0RD
      with (l := [SWin 4; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 3]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RB_1LC1RD_0LB1RA_1LB0RD
      with (l := [SWin 4; SRotL 1; SWin 1; SCycL 2 0; SWin 3]).
