    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RB_1LC1RD_0LB1RA_1LB0RD
      with (l := []).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RB_1LC1RD_0LB1RA_1LB0RD
      with (l := [SWin 4; SRotL 1; SWin 1; SCycL 2 0; SWin 4; SCycR 2; SWin 2]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RB_1LC1RD_0LB1RA_1LB0RD
      with (l := [SWin 2]).
