Lemma lapi_1RB0RB_1RC0LD_1LB0LA_0LD1RB : forall p j q0, cview p = (j, Some q0) ->
  exists n, 0 < n /\ csteps tm n (Cc p) = Some (Cc (Pos.succ p)).
Proof.
  intros p j q0 E. destruct j as [|j'].
  - destruct (gz_1RB0RB_1RC0LD_1LB0LA_0LD1RB p q0 E) as (HA & HB).
    exists (0 * 0 + 4). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chz_1RB0RB_1RC0LD_1LB0LA_0LD1RB Z0_1RB0RB_1RC0LD_1LB0LA_0LD1RB Z1_1RB0RB_1RC0LD_1LB0LA_0LD1RB 0 4
               run_z_1RB0RB_1RC0LD_1LB0LA_0LD1RB (Kp q0 ++ [S0]) [] 0
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
  - destruct (gp_1RB0RB_1RC0LD_1LB0LA_0LD1RB p j' q0 E) as (HA & HB).
    exists (4 * j' + 8). split; [lia|].
    rewrite HA.
    rewrite (srun_sound tm false true chp_1RB0RB_1RC0LD_1LB0LA_0LD1RB P0_1RB0RB_1RC0LD_1LB0LA_0LD1RB P1_1RB0RB_1RC0LD_1LB0LA_0LD1RB 4 8
               run_p_1RB0RB_1RC0LD_1LB0LA_0LD1RB (Kp q0 ++ [S0]) [] j'
               ltac:(discriminate) ltac:(reflexivity)).
    f_equal. exact HB.
Qed.

Lemma gso_1RB0RB_1RC0LD_1LB0LA_0LD1RB : forall p j, cview p = (S j, None) ->
  Cc p = cden [] [] j B0_1RB0RB_1RC0LD_1LB0LA_0LD1RB.
Proof.
