(** ** The lap *)

Lemma lap_1RB0RB_1RC1RC_1LD0RC_0LD1LA : forall p, exists n c',
  csteps tm n (Cc p) = Some c' /\ lift c' = lift (Cc (Pos.succ p)) /\ 0 < n.
