  - destruct (lapi_1RB0RB_1RC1RC_1LD0RC_0LD1LA p j q0 E) as (n & c' & Hn & Hrun & Hlift).
    exists n, c'. split; [exact Hrun | split; [exact Hlift | exact Hn]].
  - destruct (cview_pos p j E) as (j' & ->).
    apply (lap_of_run tm Cc true true cho_1RB0RB_1RC1RC_1LD0RC_0LD1LA B0_1RB0RB_1RC1RC_1LD0RC_0LD1LA B1_1RB0RB_1RC1RC_1LD0RC_0LD1LA 2 12 p j' [] []).
    + exact run_ovf_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
    + reflexivity.
    + reflexivity.
    + exact (gso_1RB0RB_1RC1RC_1LD0RC_0LD1LA p j' E).
    + exact (geo_1RB0RB_1RC1RC_1LD0RC_0LD1LA p j' E).
    + lia.
