Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RB_1RC1RC_1LD0RC_0LD1LA = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RB_1RC1RC_1LD0RC_0LD1LA p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RB_1RC1RC_1LD0RC_0LD1LA p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RB_1RC1RC_1LD0RC_0LD1LA : forall t, ~ In t pins_1RB0RB_1RC1RC_1LD0RC_0LD1LA ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n c', 0 < n /\ csteps tm n (Cc p0) = Some c'
                         /\ lift c' = lift (Cc (Pos.succ p0)))
    by exact lapi_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
  destruct t as [q b]; destruct q, b.
  - (* A0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1; SWinR 1] (StA, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* A1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StA, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1; SWinR 5] (StA, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* B0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* B1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StB, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1; SWinR 2] (StB, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1; SWinR 3] (StC, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* C1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StC, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1; SWinR 7] (StC, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D0 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S0)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [] (StD, S0) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
  - (* D1 *)
    apply (fire_csteps_of_lift tm Cc).
    apply (fire_via_ovf_lift tm Cc Hi (StD, S1)).
    intros p1 j1 E1. apply (fire_lift_of_csteps tm Cc).
    apply (fireo_1RB0RB_1RC1RC_1LD0RC_0LD1LA [SWin 1] (StD, S1) ltac:(vm_compute; reflexivity)
                   p1 j1 E1).
Qed.

Theorem qhtrm_1RB0RB_1RC1RC_1LD0RC_0LD1LA : NonHalt tmm_1RB0RB_1RC1RC_1LD0RC_0LD1LA /\ QHBoundTr 32779478 tmm_1RB0RB_1RC1RC_1LD0RC_0LD1LA /\ QuasiHaltsTr tmm_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
Proof.
  apply (lap_qh_stage tmm_1RB0RB_1RC1RC_1LD0RC_0LD1LA pins_1RB0RB_1RC1RC_1LD0RC_0LD1LA Cc 1 8 32779478).
  - exact bootq_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
  - intros p _. apply lap_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
  - intros t Ht p _. apply fire_1RB0RB_1RC1RC_1LD0RC_0LD1LA. exact Ht.
  - exact wit_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
  - apply qcleb_QC_14. reflexivity.
Qed.

Theorem qhtr_1RB0RB_1RC1RC_1LD0RC_0LD1LA : NonHalt tm_1RB0RB_1RC1RC_1LD0RC_0LD1LA /\ QHBoundTr 32779478 tm_1RB0RB_1RC1RC_1LD0RC_0LD1LA /\ QuasiHaltsTr tm_1RB0RB_1RC1RC_1LD0RC_0LD1LA.
