  - intros t Ht p _. apply fire_1RB0RB_1RC1RD_0LC1LA_1LC0RD. exact Ht.
  - exact wit_1RB0RB_1RC1RD_0LC1LA_1LC0RD.
  - apply qcleb_QC_14. reflexivity.
Qed.

