    + exact (gso_1RB0RC_0LB1RC_0RD0LA_1LB1RD p j' E).
    + exact (geo_1RB0RC_0LB1RC_0RD0LA_1LB1RD p j' E).
    + lia.
Qed.

(** ** Bootstrap *)

Lemma bootq_1RB0RC_0LB1RC_0RD0LA_1LB1RD : stepn tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD 5 InitES = Some (lift (Cc 1)).
Proof.
  assert (H : match csteps tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD 5 c0 with
              | Some c => ceqb c (Cc 1) | None => false end = true)
    by (vm_compute; reflexivity).
  destruct (csteps tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD 5 c0) as [c|] eqn:E; [|discriminate].
  rewrite <- lift_c0, (csteps_lift _ _ _ _ E). f_equal. apply ceqb_lift. exact H.
Qed.

(** the quasihalt witness: a pinned instruction fired in the prefix *)
Lemma wit_1RB0RC_0LB1RC_0RD0LA_1LB1RD : existsb (fun tg => cfires tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD c0 5 tg) pins_1RB0RC_0LB1RC_0RD0LA_1LB1RD = true.
Proof. vm_compute. reflexivity. Qed.

(** ** Visits

    Every state fires inside the OVERFLOW lap, so one prefix chain per state
    plus [LapCertGlue.vis_via_ovf] (run interior laps until the counter
    overflows -- they close exactly) covers every anchor. *)

Lemma fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD : forall (l : list lstep) (t : Instr),
  srun_instr tm true true l B0_1RB0RC_0LB1RC_0RD0LA_1LB1RD = Some t ->
  forall p j, cview p = (S j, None) ->
  exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros l t Hst p j E.
  apply (fire_of_run_instr tm Cc true true l B0_1RB0RC_0LB1RC_0RD0LA_1LB1RD p j [] []);
    [exact Hst | reflexivity | reflexivity | exact (gso_1RB0RC_0LB1RC_0RD0LA_1LB1RD p j E)].
Qed.


(** ** Fires: every UNPINNED instruction fires from every anchor
    (inside the overflow lap; [LapGlueTr.fire_via_ovf] runs the
    interior laps until the counter overflows). *)

Lemma fire_1RB0RC_0LB1RC_0RD0LA_1LB1RD : forall t, ~ In t pins_1RB0RC_0LB1RC_0RD0LA_1LB1RD ->
  forall p, exists k c, csteps tm k (Cc p) = Some c /\ cinstr c = t.
Proof.
  intros t Hnp p.
  assert (Hi : forall p0 j q0, cview p0 = (j, Some q0) ->
            exists n, 0 < n /\ csteps tm n (Cc p0) = Some (Cc (Pos.succ p0)))
    by exact lapi_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
  destruct t as [q b]; destruct q, b.
  - (* A0: pinned *)
    exfalso. apply Hnp. apply tr_inb_spec. reflexivity.
  - (* A1 *)
    apply (fire_via_ovf tm Cc Hi (StA, S1)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 2; SCycL 6 0; SWin 5]).
    vm_compute; reflexivity.
  - (* B0 *)
    apply (fire_via_ovf tm Cc Hi (StB, S0)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := []).
    vm_compute; reflexivity.
  - (* B1 *)
    apply (fire_via_ovf tm Cc Hi (StB, S1)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 1]).
    vm_compute; reflexivity.
  - (* C0 *)
    apply (fire_via_ovf tm Cc Hi (StC, S0)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 2]).
    vm_compute; reflexivity.
  - (* C1 *)
    apply (fire_via_ovf tm Cc Hi (StC, S1)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 2; SCycL 6 0; SWin 4]).
    vm_compute; reflexivity.
  - (* D0 *)
    apply (fire_via_ovf tm Cc Hi (StD, S0)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 2; SCycL 6 0; SWin 2]).
    vm_compute; reflexivity.
  - (* D1 *)
    apply (fire_via_ovf tm Cc Hi (StD, S1)), fireo_1RB0RC_0LB1RC_0RD0LA_1LB1RD
      with (l := [SWin 2; SCycL 6 0; SWin 1]).
    vm_compute; reflexivity.
Qed.

Theorem qhtrm_1RB0RC_0LB1RC_0RD0LA_1LB1RD : NonHalt tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD /\ QHBoundTr 32779478 tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD /\ QuasiHaltsTr tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
Proof.
  apply (lap_qh_stage tmm_1RB0RC_0LB1RC_0RD0LA_1LB1RD pins_1RB0RC_0LB1RC_0RD0LA_1LB1RD Cc 1 5 32779478).
  - exact bootq_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
  - intros p _. apply lap_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
  - intros t Ht p _. apply fire_1RB0RC_0LB1RC_0RD0LA_1LB1RD. exact Ht.
  - exact wit_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
  - apply qcleb_QC_14. reflexivity.
Qed.

Theorem qhtr_1RB0RC_0LB1RC_0RD0LA_1LB1RD : NonHalt tm_1RB0RC_0LB1RC_0RD0LA_1LB1RD /\ QHBoundTr 32779478 tm_1RB0RC_0LB1RC_0RD0LA_1LB1RD /\ QuasiHaltsTr tm_1RB0RC_0LB1RC_0RD0LA_1LB1RD.
Proof. apply (qh_triple_unmirror 32779478 tm_1RB0RC_0LB1RC_0RD0LA_1LB1RD). rewrite mirror_ok_1RB0RC_0LB1RC_0RD0LA_1LB1RD. exact qhtrm_1RB0RC_0LB1RC_0RD0LA_1LB1RD. Qed.

